SELECT NTE.ID, NTE.REFERENCIA, NTE.CODEMP, NTE_DET.ID AS ID_CAB, NTE_DET.NOTA, NTE_DET.TITULO, NTE_DET.DESCRICAO FROM NOTAS_EXPLICATIVAS_CAB NTE INNER JOIN NOTAS_EXPLICATIVAS_DET NTE_DET ON NTE.ID = NTE_DET.ID_NOTAS_EXPLICATIVAS_CAB WHERE NTE.CODEMP = :VAR_EMPRESA_DRE   AND NTE.REFERENCIA = (         SELECT MAX(C2.REFERENCIA)         FROM NOTAS_EXPLICATIVAS_CAB C2         WHERE C2.CODEMP = :VAR_EMPRESA_DRE           AND C2.REFERENCIA <= DATE(:VAR_DATA_REF_DRE)       ) ORDER BY CAST(SUBSTRING_INDEX(CONCAT(NTE_DET.NOTA, '.0.0.0'), '.', 1) AS UNSIGNED),          CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(NTE_DET.NOTA, '.0.0.0'), '.', 2), '.', -1) AS UNSIGNED),          CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(NTE_DET.NOTA, '.0.0.0'), '.', 3), '.', -1) AS UNSIGNED),          CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(NTE_DET.NOTA, '.0.0.0'), '.', 4), '.', -1) AS UNSIGNED)